import { compileScript, compileTemplate, parse } from '@vue/compiler-sfc'

test('repro', () => {
  const src = `<script setup>
const props = defineProps({ backgroundColor: { type: String, default: 'blue' } })
</script>
<template>
  <ComponentTest class="parent-component">
    <div class="child-content">Hello</div>
  </ComponentTest>
</template>
<style scoped>
.parent-component { background-color: v-bind('props.backgroundColor') }
</style>`
  const { descriptor } = parse(src)
  const s = compileScript(descriptor, {
    id: 'xxx',
    inlineTemplate: true,
    templateOptions: { ssr: true },
  })
  console.log(s.content)
  const c = `<template><div :style="{ display }"><slot /></div></template>`
  const d2 = parse(c).descriptor
  console.log(
    compileTemplate({
      source: d2.template!.content,
      filename: 'b.vue',
      id: 'b',
      ssr: true,
    }).code,
  )
})

