import { createSSRApp, h, useCssVars } from 'vue'

test('repro', () => {
  const container = document.createElement('div')
  container.innerHTML = `<div style="display:flex;--foo:red;"><div class="child-content">Hello</div></div>`
  const Child = {
    setup(_: any, { slots }: any) {
      return () => h('div', { style: { display: 'flex' } }, slots.default())
    },
  }
  const app = createSSRApp({
    setup() {
      useCssVars(() => ({ foo: 'red' }))
      return () =>
        h(Child, null, { default: () => h('div', { class: 'child-content' }, 'Hello') })
    },
  })
  app.mount(container)
  expect(`Hydration style mismatch`).not.toHaveBeenWarned()
})

