import { compileScript, parse } from '@vue/compiler-sfc'
import * as Vue from 'vue'
import * as SR from '@vue/server-renderer'

function load(src: string, ssr: boolean, id: string) {
  const { descriptor } = parse(src)
  const s = compileScript(descriptor, {
    id,
    inlineTemplate: true,
    templateOptions: { ssr },
  })
  let code = s.content
    .replace(/import \{([^}]*)\} from "vue\/server-renderer"/g, (_, a) =>
      `const {${a.replace(/ as /g, ': ')}} = SR`)
    .replace(/import \{([^}]*)\} from "vue"/g, (_, a) =>
      `const {${a.replace(/ as /g, ': ')}} = Vue`)
    .replace(/import ComponentTest from '.\/ComponentTest.vue'/, '')
    .replace('export default', 'return')
  console.log(code)
  return new Function('Vue', 'SR', 'ComponentTest', code)
}

const appSrc = `<script setup>
import ComponentTest from './ComponentTest.vue'
const props = defineProps({
  backgroundColor: { type: String, default: 'blue' },
  padding: { type: String, default: '20px' }
})
</script>
<template>
  <ComponentTest class="parent-component">
    <div class="child-content">Hello</div>
  </ComponentTest>
</template>
<style scoped>
.parent-component { background-color: v-bind('props.backgroundColor') }
.child-content { color: #fff; padding: v-bind('props.padding') }
</style>`
const childSrc = `<template>
  <div :style="{ display }"><slot name="default" /></div>
</template>
<script setup>
defineProps({ display: { type: String, default: 'flex' } })
</script>`

test('repro', async () => {
  const ssrChild = load(childSrc, true, 'ccc')(Vue, SR)
  const ssrApp = load(appSrc, true, 'aaa')(Vue, SR, ssrChild)
  const html = await SR.renderToString(Vue.createSSRApp(ssrApp))
  console.log(html)
  const child = load(childSrc, false, 'ccc')(Vue, SR)
  const app = load(appSrc, false, 'aaa')(Vue, SR, child)
  const container = document.createElement('div')
  container.innerHTML = html
  Vue.createSSRApp(app).mount(container)
  expect(`Hydration style mismatch`).not.toHaveBeenWarned()
})

